// 2025-1-24 1309
// 又画彭罗斯
// https://www.shadertoy.com/view/X33fW2

//#define X(a,b)   abs(cross(a,b).z)
#define C(a,b,c) cross(a-d,b-d).z*cross(c-d,b-d).z>0.

float L(vec3 a, vec3 b, vec3 p){
        b-=a; p-=a;
        return length(p - b * clamp(dot(p,b)/dot(b,b), 0., 1.));
}

void mainImage(out vec4 O, vec2 U)
{
        vec3 R = iResolution,u,v;
             u.xy = .2 * (U+U - R.xy)/ R.y;v=u;u.x+=R.x/R.y;
        vec3 a,b,c,d,e;
        c.y = 1.; b=-c; a.x = tan(6.28/5.);
        float i,T, g=.618;
        for(;i<10.;i++){
                d = a + (b-a)*g;
                e = c + (a-c)*g;
                if(T>.5){
                        if(C(a,c,u)) 
                          T=0.,b=c,c=d;
                        else  a=b,b=c,c=d;
                }else{        

                        if(C(a,e,u))
                          T=1., b=d,c=e;
                        else if( C(b,c,u))
                            a=c,c=b,b=d;
                        else 
                            a=c,b=d,c=e;
                }
        }

        if(T>.5)e=b,b=c,c=e,g=1.-g;//or ,g*=g;
        vec3 pm;
        if(abs(iTime-10.)>.5)
        pm.xy = vec2(.2,.1)*vec2(sin(iTime*1.1213),sin(iTime*5.7317));
        //T = 1.-T;
        O= .6*(2.-T) *
        ((length(v-pm)>.16)^^(iMouse.x<R.x*.51)
        ? vec4(.01,.5,1.,1).zyxw  // blue    y
        : vec4(.01,.5,1.,1).yxzw)  // green   p
        //.yzxw *.5 //purple   g 
        ////.xyzw  // orange  b
        //.xzyw  // red
        +.0 + .2* smoothstep(.0015,.001,min(L(a,b,u), L(c,b,u)));              
        //O -= .1*smoothstep(.0041,.004, abs(length(u-a)-length(a-c)*g));
        O =1.-O;        
        O.y += smoothstep(.0021,.002, abs(length(v-pm)-.16));
}
